'use strict';
// Curated information, not a harmonized genealogy. Sources reviewed 2026-10-22.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..'),L=(nl,en,fr)=>({nl,en,fr}),id=s=>`islam:${s}`;
const people=[],relationships=[],places=[],families=[];
const Q=(s,v,end=v)=>({id:`q-${s}-${v}-${end}`,kind:'scripture',label:L(`Koran ${s}:${v}${end===v?'':`–${end}`}`,`Qur’an ${s}:${v}${end===v?'':`–${end}`}`,`Coran ${s},${v}${end===v?'':`–${end}`}`),url:`https://quran.com/${s}/${v}${end===v?'':`-${end}`}`,passage:{tradition:'islam',edition:'nl',surah:s,verse:v,endVerse:end}});
const R=(key,kind,label,url)=>({id:key,kind,label,url});
const H=(collection,num)=>R(`${collection}-${String(num).replace(/\W/g,'-')}`,'tradition',L(`${collection==='bukhari'?'Sahih al-Bukhari':'Sahih Muslim'} ${num}`,`${collection==='bukhari'?'Sahih al-Bukhari':'Sahih Muslim'} ${num}`,`${collection==='bukhari'?'Sahih al-Bukhari':'Sahih Muslim'} ${num}`),`https://sunnah.com/${collection}:${num}`);
const ahl=R('fatima-biography','tradition',L('Al-Qurashi: Fatima en haar gezin · sjiitische biografie','Al-Qurashi: Fatima and her family · Shi‘i biography','Al-Qurashi : Fatima et sa famille · biographie chiite'),'https://al-islam.org/life-fatimah-az-zahra-principal-all-women-study-and-analysis-baqir-sharif-al-qurashi/fatimah-quran');
const P=(key,name,summary,refs,indexKey=key,aliases=[])=>{const p={id:id(key),name,aliases,summary,refs};if(indexKey)p.indexId=`quran:${indexKey}`;people.push(p);};
const E=(a,b,type,summary,refs)=>relationships.push({id:id(`rel-${a}-${b}-${type}`),source:id(a),target:id(b),type,summary,refs});
const F=(key,title,summary,keys)=>families.push({id:id(`family-${key}`),title,summary,personIds:keys.map(id)});
const C=(key,name,kind,summary,historicalContext,locationNote,keys,refs,aliases=[])=>places.push({id:id(key),name,aliases,kind,summary,historicalContext,locationNote,personIds:keys.map(id),refs});

P('abraham',L('Ibrahim','Ibrahim','Ibrâhîm'),L('Vader van Ismail en Ishaq; met Ismail verbonden aan het heilige Huis.','Father of Ismail and Ishaq; associated with the Sacred House alongside Ismail.','Père d’Ismâïl et d’Ishâq ; associé à la Maison sacrée avec Ismâïl.'),[Q(14,39),Q(2,125,127)],'abraham',['Abraham','إبراهيم']);
