E('noah','noah-son','parent',L('11:42 noemt hem Nuhs zoon; 11:46 maakt religieus behoren tot het gezin tot een afzonderlijke kwestie.','11:42 calls him Nuh’s son; 11:46 makes religious membership of the household a separate issue.','11,42 le nomme fils de Nûh ; 11,46 traite séparément de son appartenance religieuse à la famille.'),[Q(11,42,46)]);
E('muhammad','khadija','spouse',L('Het huwelijksverband is ontleend aan de hadithtraditie, niet aan een naamvermelding in de Koran.','The marriage comes from hadith tradition, not from a naming in the Qur’an.','Le mariage provient de la tradition du hadith, non d’une mention nominative dans le Coran.'),[H('bukhari',3821)]);
E('muhammad','fatima','parent',L('Al-Bukhari noemt Fatima expliciet zijn dochter.','Al-Bukhari explicitly calls Fatima his daughter.','Al-Bukhari désigne explicitement Fâtima comme sa fille.'),[H('bukhari',3715)]);
E('ali','fatima','spouse',L('De overlevering beschrijft hun gezamenlijke huishouden.','The tradition describes their shared household.','La tradition décrit leur foyer commun.'),[H('bukhari',5361),ahl]);
for(const child of ['hasan','husayn']){
 E('ali',child,'parent',L(`${child==='hasan'?'Hasan':'Husayn'} is in de overlevering een zoon van Ali.`,`${child==='hasan'?'Hasan':'Husayn'} is a son of Ali in the tradition.`,`${child==='hasan'?'Hasan':'Husayn'} est un fils de ‘Alî dans la tradition.`),[H('muslim',2424),ahl]);
 E('fatima',child,'parent',L(`${child==='hasan'?'Hasan':'Husayn'} is in de overlevering een zoon van Fatima.`,`${child==='hasan'?'Hasan':'Husayn'} is a son of Fatima in the tradition.`,`${child==='hasan'?'Hasan':'Husayn'} est un fils de Fâtima dans la tradition.`),[ahl]);
}
E('muhammad','zayd','adoptive',L('Voormalige adoptierelatie volgens de hadith. Koran 33:4–5 onderscheidt adoptie van afstamming; dit is geen biologische ouderlijn.','Former adoptive relationship according to hadith. Qur’an 33:4–5 distinguishes adoption from descent; this is not a biological parent line.','Ancien lien adoptif selon le hadith. Le Coran 33,4–5 distingue adoption et filiation ; ce n’est pas une parenté biologique.'),[H('bukhari',4782),Q(33,4,5)]);
E('david','solomon','parent',L('Sulayman wordt aan Dawud geschonken en volgt hem op; de kaart gebruikt de gangbare islamitische vader-zoonlezing.','Sulayman is granted to Dawud and succeeds him; the map uses the standard Islamic father–son reading.','Sulaymân est accordé à Dâwûd et lui succède ; la carte suit la lecture islamique habituelle de père et fils.'),[Q(38,30),Q(27,16)]);

F('ibrahim',L('Ibrahim en zijn nakomelingen','Ibrahim and his descendants','Ibrâhîm et sa descendance'),L('Koranverhalen en een afzonderlijk gelabelde hadithgenealogie. De naam van de zoon in het offerverhaal wordt niet ingevuld.','Qur’anic narratives and a separately labelled hadith genealogy. The son in the sacrifice narrative is not assigned a name.','Récits coraniques et généalogie du hadith identifiée séparément. Aucun nom n’est attribué au fils du récit du sacrifice.'),['abraham','abraham-wife','ishmael','isaac','jacob','joseph','joseph-brother']);
F('musa',L('Musa, Harun en het gezin','Musa, Harun and family','Mûsâ, Hârûn et leur famille'),L('Familie en huwelijk in het Korannarratief. Naamloze personen blijven naamloos; de vader in Madyan wordt niet als Shuayb ingevuld.','Family and marriage in the Qur’anic narrative. Unnamed figures remain unnamed; the father in Madyan is not labelled Shuayb.','Famille et mariage dans le récit coranique. Les anonymes le restent ; le père à Madyan n’est pas nommé Chu‘ayb.'),['moses','aaron','moses-mother','moses-sister','midian-elder','moses-wife']);
F('maryam',L('Maryam, Isa en Zakariya','Maryam, Isa and Zakariya','Maryam, Îsâ et Zakariyyâ'),L('Ouderschap en zorg worden apart getoond. De aanspreking “zus van Harun” wordt niet opgevat als een directe zusterrelatie met Musa’s broer.','Parenthood and care are shown separately. The address “sister of Harun” is not treated as a direct sibling relationship with Musa’s brother.','Parenté et prise en charge sont distinguées. L’appellation « sœur de Hârûn » n’est pas interprétée comme une relation directe de fratrie avec le frère de Mûsâ.'),['imran','mary-mother','mary','jesus','zechariah','zechariah-wife','john-baptist']);
F('nuh',L('Nuh en zijn gezin','Nuh and his household','Nûh et sa famille'),L('De vloedvertelling maakt het verschil tussen verwantschap en geloof zichtbaar. De kaart noemt geen niet-overgeleverde namen.','The flood narrative distinguishes kinship and faith. The map supplies no names absent from its sources.','Le récit du déluge distingue parenté et foi. La carte n’ajoute aucun nom absent de ses sources.'),['noah','noah-wife','noah-son']);
F('muhammad',L('Een deel van Mohammeds gezin','Part of Muhammad’s household','Une partie de la famille de Muhammad'),L('Een selectie, geen volledige stamboom. Hadith en sjiitische biografische uitleg zijn herkenbaar gelabeld. De lijn naar Zayd is voormalige adoptie; er wordt geen afstammingsketen naar Ibrahim getekend.','A selection, not a complete genealogy. Hadith and Shi‘i biographical interpretation are explicitly labelled. The Zayd link is former adoption; no chain of descent to Ibrahim is drawn.','Une sélection, non une généalogie complète. Hadith et interprétation biographique chiite sont explicitement signalés. Le lien à Zayd est une ancienne adoption ; aucune lignée jusqu’à Ibrâhîm n’est tracée.'),['muhammad','khadija','fatima','ali','hasan','husayn','zayd']);
F('dawud',L('Dawud en Sulayman','Dawud and Sulayman','Dâwûd et Sulaymân'),L('Een vader-zoonverband in de islamitische lezing, zonder de uitgebreide Bijbelse koningsgenealogie over te nemen.','A father–son connection in the Islamic reading, without importing the extended biblical royal genealogy.','Un lien père-fils dans la lecture islamique, sans importer la longue généalogie royale biblique.'),['david','solomon']);

C('mecca',L('Mekka','Mecca','La Mecque'),'city',L('Centrum van de bedevaart en plaats van het heilige Huis. Ibrahim en Ismail worden met de bouw van het Huis verbonden.','Centre of pilgrimage and site of the Sacred House. Ibrahim and Ismail are associated with raising the House.','Centre du pèlerinage et lieu de la Maison sacrée. Ibrâhîm et Ismâïl sont associés à son édification.'),L('Koran 48 situeert het conflict rond toegang tot het heiligdom bij Mekka. De tekst verbindt heilige ruimte met de geschiedenis van Mohammeds gemeenschap.','Qur’an 48 situates the conflict over access to the sanctuary at Mecca, linking sacred space with the history of Muhammad’s community.','Le Coran 48 situe à La Mecque le conflit concernant l’accès au sanctuaire, reliant l’espace sacré à l’histoire de la communauté de Muhammad.'),L('Een bekende stad; de religieuze oorsprongsvertelling is iets anders dan een archeologische datering van de Kaäba.','An identifiable city; the religious origin narrative is distinct from an archaeological dating of the Kaaba.','Ville identifiable ; le récit religieux des origines se distingue d’une datation archéologique de la Kaaba.'),['abraham','ishmael','muhammad'],[Q(2,125,127),Q(48,24,25)],['Makkah','Bakka','Kaäba','Kaaba']);
C('medina',L('Medina · Yathrib','Medina · Yathrib','Médine · Yathrib'),'city',L('De stad van Mohammeds gemeenschap na de migratie uit Mekka. De Koran gebruikt zowel Yathrib als al-Madina.','The city of Muhammad’s community after migration from Mecca. The Qur’an uses both Yathrib and al-Madina.','Ville de la communauté de Muhammad après la migration depuis La Mecque. Le Coran emploie Yathrib et al-Madîna.'),L('De hadith vertelt over de emigratie en de vestiging van de gemeenschap. Koran 33:13 beschrijft een crisismoment bij Yathrib.','Hadith recounts migration and the community’s settlement. Qur’an 33:13 describes a crisis at Yathrib.','Le hadith relate la migration et l’établissement de la communauté. Le Coran 33,13 décrit une crise à Yathrib.'),L('Yathrib en Medina verwijzen hier naar dezelfde stad; niet elk onbepaald “de stad” elders in de Koran betekent Medina.','Yathrib and Medina refer here to the same city; not every unspecified “city” elsewhere in the Qur’an means Medina.','Yathrib et Médine désignent ici la même ville ; toute « ville » non précisée ailleurs dans le Coran ne signifie pas Médine.'),['muhammad'],[Q(33,13),Q(9,120),H('bukhari',3905)],['Madinah','al-Madina']);
C('jerusalem',L('Jeruzalem · al-Quds','Jerusalem · al-Quds','Jérusalem · al-Quds'),'city',L('In de islamitische traditie verbonden met de nachtelijke reis naar al-Masjid al-Aqsa en de hemelreis van Mohammed.','Connected in Islamic tradition with Muhammad’s night journey to al-Masjid al-Aqsa and ascent.','Associée dans la tradition islamique au voyage nocturne de Muhammad vers al-Masjid al-Aqsa et à son ascension.'),L('De Rotskoepel bewaart de herinnering aan een heilige rots en de hemelreis. Het museum beschrijft de verschillende religieuze betekenissen van deze plek.','The Dome of the Rock preserves remembrance of a sacred rock and the ascent. The museum describes the site’s different religious meanings.','Le Dôme du Rocher conserve la mémoire d’un rocher sacré et de l’ascension. Le musée décrit les différentes significations religieuses du lieu.'),L('Koran 17:1 noemt Jeruzalem niet bij naam. De identificatie van het “verste gebedshuis” met Jeruzalem behoort tot de islamitische uitlegtraditie.','Qur’an 17:1 does not name Jerusalem. Identification of the “farthest mosque” with Jerusalem belongs to Islamic interpretive tradition.','Le Coran 17,1 ne nomme pas Jérusalem. L’identification du « lieu de prière le plus éloigné » à Jérusalem relève de la tradition interprétative islamique.'),['muhammad'],[Q(17,1),R('met-jerusalem','historical',L('Metropolitan Museum: Jeruzalem en de Rotskoepel','Metropolitan Museum: Jerusalem and the Dome of the Rock','Metropolitan Museum : Jérusalem et le Dôme du Rocher'),'https://www.metmuseum.org/exhibitions/listings/2016/jerusalem/exhibition-galleries')],['Al-Quds','Bayt al-Maqdis','Al-Aqsa']);
C('badr',L('Badr','Badr','Badr'),'settlement',L('Badr wordt bij naam genoemd in de herinnering aan goddelijke hulp aan de vroege gemeenschap.','Badr is named in the recollection of divine aid to the early community.','Badr est nommé dans le rappel de l’aide divine à la première communauté.'),L('De Korantekst interpreteert de confrontatie in termen van kwetsbaarheid, geduld en hulp. Dit is een religieuze duiding van strijd.','The Qur’anic text interprets the confrontation through vulnerability, patience and aid. This is a religious interpretation of battle.','Le texte coranique interprète l’affrontement en termes de vulnérabilité, de patience et d’aide. Il s’agit d’une lecture religieuse du combat.'),L('De plaatsnaam duidt de omgeving van de confrontatie aan; de passage geeft geen moderne terreingrenzen.','The place name indicates the setting of the confrontation; the passage gives no modern site boundaries.','Le toponyme indique le cadre de l’affrontement ; le passage ne donne pas de limites modernes du site.'),['muhammad'],[Q(3,123,125)]);
C('hunayn',L('Hunayn','Hunayn','Hunayn'),'region',L('De dag van Hunayn wordt herinnerd als een moment waarop numeriek overwicht geen veiligheid bood.','The day of Hunayn is remembered as a moment when numerical superiority offered no security.','Le jour de Hunayn est rappelé comme un moment où la supériorité numérique n’a pas assuré la sécurité.'),L('De verzen verbinden terugtocht en daaropvolgende rust met Mohammed en zijn gemeenschap. Ze geven betekenis aan een militaire ervaring.','The verses associate retreat and ensuing reassurance with Muhammad and his community, giving meaning to a military experience.','Les versets associent retraite et apaisement à Muhammad et à sa communauté, donnant sens à une expérience militaire.'),L('Een strijdgebied, geen afzonderlijk in deze tekst beschreven stad. Er wordt geen exact modern strijdtoneel vastgelegd.','A battle area, not a separately described city in this text. No exact modern battlefield is fixed.','Une zone de combat, non une ville décrite séparément dans ce texte. Aucun champ de bataille moderne exact n’est fixé.'),['muhammad'],[Q(9,25,26)]);
C('safa-marwa',L('Safa en Marwa','Safa and Marwa','Safâ et Marwa'),'sanctuary',L('Twee rituele plaatsen die in de Koran behoren tot de tekenen van God bij hadj en umra.','Two ritual sites counted in the Qur’an among God’s signs in hajj and umra.','Deux lieux rituels comptés dans le Coran parmi les signes de Dieu lors du hajj et de la ‘umra.'),L('De hadith over Mohammeds bedevaart beschrijft de gang tussen beide plaatsen. Zo is de korte Korantekst verbonden met een uitvoeriger rituele overlevering.','The hadith of Muhammad’s pilgrimage describes movement between the sites, connecting the brief Qur’anic passage with a fuller ritual tradition.','Le hadith du pèlerinage de Muhammad décrit le parcours entre ces lieux, reliant le bref passage coranique à une tradition rituelle plus développée.'),L('Onderdeel van het Mekkaanse heiligdom. Dit item toont rituele topografie, geen aparte stad.','Part of the Meccan sanctuary. This entry concerns ritual topography, not a separate city.','Partie du sanctuaire mecquois. Cette notice concerne une topographie rituelle, non une ville distincte.'),['muhammad'],[Q(2,158),H('muslim','1218a')],['As-Safa','Al-Marwah','sa’i']);
C('arafat',L('Arafat','Arafat','‘Arafât'),'region',L('Een bedevaartsplaats die de Koran noemt bij het vertrek van de pelgrims en het gedenken van God.','A pilgrimage site named by the Qur’an when describing pilgrims’ departure and remembrance of God.','Lieu de pèlerinage nommé par le Coran à propos du départ des pèlerins et du rappel de Dieu.'),L('De hadith over Mohammeds bedevaart beschrijft het verblijf bij Arafat binnen een reeks rituele handelingen.','The hadith of Muhammad’s pilgrimage describes the stay at Arafat within a sequence of rituals.','Le hadith du pèlerinage de Muhammad décrit le séjour à ‘Arafât dans une suite de rites.'),L('Een ritueel landschap bij Mekka; de tekst biedt geen kadastrale afbakening van het huidige gebied.','A ritual landscape near Mecca; the text supplies no cadastral boundary for the present area.','Paysage rituel près de La Mecque ; le texte ne fournit pas de délimitation cadastrale de la zone actuelle.'),['muhammad'],[Q(2,198,199),H('muslim','1218a')]);
C('sinai',L('Sinai en de vallei Tuwa','Sinai and the valley of Tuwa','Sinaï et vallée de Tuwâ'),'mountain',L('De roeping van Musa speelt zich af bij vuur en een heilige vallei; elders noemt de Koran de berg Sinai.','Musa’s calling takes place beside fire and a sacred valley; elsewhere the Qur’an names Mount Sinai.','L’appel de Mûsâ se situe près d’un feu et d’une vallée sacrée ; ailleurs le Coran nomme le mont Sinaï.'),L('UNESCO beschrijft Jebel Musa als een berg die door moslims wordt vereerd in het landschap van Sint-Catharina. Dit is gedeeld religieus erfgoed.','UNESCO describes Jebel Musa as a mountain revered by Muslims in the Saint Catherine landscape: shared religious heritage.','L’UNESCO décrit le djebel Musa comme une montagne vénérée par les musulmans dans le paysage de Sainte-Catherine : un patrimoine religieux partagé.'),L('De latere identificatie met Jebel Musa bewijst geen exacte historische locatie van de Koranscène. Tuwa krijgt geen verzonnen coördinaten.','The later identification with Jebel Musa does not prove the Qur’anic scene’s exact historical location. No coordinates are invented for Tuwa.','L’identification ultérieure au djebel Musa ne prouve pas la localisation historique exacte de la scène coranique. Aucune coordonnée n’est inventée pour Tuwâ.'),['moses'],[Q(20,9,14),Q(23,20),R('unesco-sinai','historical',L('UNESCO: gebied van Sint-Catharina','UNESCO: Saint Catherine Area','UNESCO : Zone Sainte-Catherine'),'https://whc.unesco.org/en/list/954/')],['Jebel Musa','Tur','Sinaï']);
C('midian',L('Madyan · Midjan','Madyan · Midian','Madyan'),'region',L('Musa bereikt een waterplaats in Madyan. In een afzonderlijke verhaallijn wordt Shuayb tot Madyan gezonden.','Musa reaches a watering place in Madyan. In a separate narrative, Shuayb is sent to Madyan.','Mûsâ atteint un point d’eau à Madyan. Dans un récit distinct, Chu‘ayb est envoyé à Madyan.'),L('De verhaallijnen leggen nadruk op gastvrijheid, arbeid en rechtvaardigheid in handel. De naamloze vader bij de bron is niet in de tekst geïdentificeerd als Shuayb.','The narratives emphasise hospitality, work and fair trade. The unnamed father at the well is not identified as Shuayb in the text.','Les récits soulignent hospitalité, travail et équité commerciale. Le père anonyme près du puits n’est pas identifié à Chu‘ayb dans le texte.'),L('De Korantekst legt geen precieze moderne vindplaats vast. Een traditionele identificatie mag niet als bewezen opgravingslocatie worden gelezen.','The Qur’anic text fixes no precise modern site. A traditional identification should not be treated as a proven excavation location.','Le texte coranique ne fixe aucun site moderne précis. Une identification traditionnelle ne vaut pas localisation archéologique démontrée.'),['moses','midian-elder','moses-wife','shuayb'],[Q(28,22,28),Q(7,85)],['Midian','Midjan']);
C('egypt',L('Egypte · Misr','Egypt · Misr','Égypte · Misr'),'region',L('Egypte is het decor van Yusufs hereniging met zijn familie en van Musa’s conflict met Farao.','Egypt is the setting of Yusuf’s reunion with his family and Musa’s conflict with Pharaoh.','L’Égypte est le cadre des retrouvailles de Yûsuf avec sa famille et du conflit de Mûsâ avec Pharaon.'),L('De Koran noemt Egypte maar dateert deze verhalen niet volgens Egyptische dynastieën. Een verhaalde koning of farao krijgt daarom geen modern toegewezen historische identiteit.','The Qur’an names Egypt but does not date these stories by Egyptian dynasties. A narrated king or pharaoh is therefore not assigned a modern historical identification.','Le Coran nomme l’Égypte sans dater ces récits par dynasties égyptiennes. Le roi ou pharaon du récit ne reçoit donc pas d’identification historique moderne.'),L('Een land en verhalende regio, geen afzonderlijke stad. Huidige landsgrenzen worden niet op de tekst geprojecteerd.','A country and narrative region, not a separate city. Present national borders are not projected onto the text.','Un pays et une région narrative, non une ville distincte. Les frontières actuelles ne sont pas projetées sur le texte.'),['joseph','jacob','moses'],[Q(12,99,100),Q(10,87),Q(43,51)],['Misr']);
C('babylon',L('Babylon · Babil','Babylon · Babil','Babylone · Bâbil'),'city',L('Babil wordt genoemd in het vers over Harut, Marut, magie en de ontkenning dat Sulayman ongelovig was.','Babil is named in the verse about Harut, Marut, magic and the denial that Sulayman disbelieved.','Bâbil est nommé dans le verset sur Hârût, Mârût, la magie et la négation de l’incroyance de Sulaymân.'),L('UNESCO beschrijft Babylon als hoofdstad van opeenvolgende rijken en als belangrijk Mesopotamisch erfgoed. Deze archeologische geschiedenis staat naast de religieuze betekenis.','UNESCO describes Babylon as the seat of successive empires and major Mesopotamian heritage. This archaeological history stands alongside the religious meaning.','L’UNESCO décrit Babylone comme siège d’empires successifs et patrimoine majeur de Mésopotamie. Cette histoire archéologique accompagne la signification religieuse.'),L('De gedeelde passage betekent niet dat Sulayman in Babylon woonde. Het archeologische Babylon is geen bewijs voor elk element van het religieuze verhaal.','Sharing this passage does not mean Sulayman lived in Babylon. Archaeological Babylon does not prove every element of the religious narrative.','Le passage commun ne signifie pas que Sulaymân habitait Babylone. Le site archéologique ne prouve pas chaque élément du récit religieux.'),['solomon'],[Q(2,102),R('unesco-babylon','historical',L('UNESCO: Babylon','UNESCO: Babylon','UNESCO : Babylone'),'https://whc.unesco.org/en/list/278/')],['Babel','Babil']);
C('sheba',L('Saba','Sheba · Saba','Saba'),'region',L('Het rijk van de naamloze koningin die in Sulaymans verhaal verschijnt. Saba heeft ook een eigen Korantekst over tuinen en een overstroming.','The realm of the unnamed queen in Sulayman’s narrative. Sheba also has a separate Qur’anic account of gardens and a flood.','Royaume de la reine anonyme du récit de Sulaymân. Saba apparaît aussi dans un récit coranique distinct de jardins et d’inondation.'),L('UNESCO documenteert het oude koninkrijk Saba rond Marib met nederzettingen, tempels en irrigatie. Archeologie ondersteunt de geschiedenis van het rijk, niet automatisch de identiteit van de verhaalde koningin.','UNESCO documents ancient Saba around Marib through settlements, temples and irrigation. Archaeology supports the kingdom’s history, not automatically the narrated queen’s identity.','L’UNESCO documente l’ancien Saba autour de Marib par ses établissements, temples et systèmes d’irrigation. L’archéologie éclaire le royaume, sans identifier automatiquement la reine du récit.'),L('Een koninkrijk en regio; Saba wordt niet eenvoudig gelijkgesteld aan één moderne stad.','A kingdom and region; Sheba is not simply equated with one modern city.','Un royaume et une région ; Saba n’est pas simplement assimilé à une ville moderne.'),['queen-sheba','solomon'],[Q(27,22,44),Q(34,15,17),R('unesco-saba','historical',L('UNESCO: monumenten van het oude Saba, Marib','UNESCO: Landmarks of Ancient Saba, Marib','UNESCO : hauts lieux de l’ancien Saba, Marib'),'https://whc.unesco.org/en/list/1700/')],['Sheba','Marib','Ma’rib']);
C('hijr',L('Al-Hijr · Hegra','Al-Hijr · Hegra','Al-Hijr · Hégra'),'settlement',L('De Koran noemt de bewoners van al-Hijr en hun uit rotsen gehouwen huizen. Overleveringen verbinden het gebied met Thamud en Salih.','The Qur’an names the people of al-Hijr and their rock-cut dwellings. Traditions connect the area with Thamud and Salih.','Le Coran nomme les habitants d’al-Hijr et leurs demeures taillées dans la roche. Des traditions relient la région à Thamûd et Sâlih.'),L('De zichtbare monumentale graven van Hegra zijn volgens UNESCO vooral Nabatees, uit de eerste eeuw v.Chr. en de eerste eeuw n.Chr. Dat moet onderscheiden blijven van het Korannarratief.','According to UNESCO, Hegra’s visible monumental tombs are principally Nabataean, from the first century BCE and first century CE. This must remain distinct from the Qur’anic narrative.','Selon l’UNESCO, les tombes monumentales visibles d’Hégra sont surtout nabatéennes, des premier siècle avant et premier siècle après notre ère. Cela reste distinct du récit coranique.'),L('De overgeleverde identificatie met het volk van Salih is geen archeologische toeschrijving van alle zichtbare graven aan dat volk.','The traditional identification with Salih’s people is not an archaeological attribution of all visible tombs to that people.','L’identification traditionnelle au peuple de Sâlih n’attribue pas archéologiquement toutes les tombes visibles à ce peuple.'),['salih','muhammad'],[Q(15,80,84),Q(7,73,74),H('bukhari',3378),R('unesco-hegra','historical',L('UNESCO: archeologisch Hegra','UNESCO: Hegra Archaeological Site','UNESCO : site archéologique d’Hégra'),'https://whc.unesco.org/en/list/1293/')],['Mada’in Salih','Hegra']);
C('judi',L('Al-Judi','Al-Judi','Al-Jûdî'),'mountain',L('De plaats waar de ark in het Koranverhaal tot rust komt nadat het water wegtrekt.','The place where the Ark settles in the Qur’anic narrative after the water recedes.','Lieu où l’Arche se pose dans le récit coranique après le retrait des eaux.'),L('Het vers maakt deel uit van Nuhs vloedverhaal. Het beschrijft een religieuze gebeurtenis, geen opgravingsverslag of routebeschrijving.','The verse belongs to Nuh’s flood narrative. It describes a religious event, not an excavation report or itinerary.','Le verset appartient au récit du déluge de Nûh. Il décrit un événement religieux, non un rapport de fouilles ni un itinéraire.'),L('De tekst geeft de naam al-Judi, maar geen moderne coördinaten. De kaart kiest geen omstreden identificatie als vaststaand feit.','The text gives the name al-Judi but no modern coordinates. The map does not present a disputed identification as established fact.','Le texte donne le nom al-Jûdî, sans coordonnées modernes. La carte ne présente pas une identification disputée comme un fait établi.'),['noah'],[Q(11,44)],['Judi','Cudi']);
C('ahqaf',L('Al-Ahqaf','Al-Ahqaf','Al-Ahqâf'),'region',L('Het duinlandschap in het waarschuwingsverhaal over Ad. De boodschapper wordt elders Hud genoemd.','The dune landscape in the warning narrative about Ad. Elsewhere the messenger is named Hud.','Paysage de dunes du récit d’avertissement adressé aux ‘Âd. Ailleurs, le messager est nommé Hûd.'),L('De beschrijving van wind, dalen en verlaten woningen heeft een waarschuwende functie in het verhaal. Zij vormt op zichzelf geen identificatie van een opgegraven stad.','The description of wind, valleys and deserted dwellings serves a warning purpose in the narrative. It does not by itself identify an excavated city.','La description du vent, des vallées et des demeures désertées remplit une fonction d’avertissement. Elle n’identifie pas à elle seule une ville fouillée.'),L('Een landschap, niet een bij naam genoemde stad. Geen exacte moderne ligging of gelijkstelling met Ubar wordt als bewezen gegeven.','A landscape, not a city named as such. No exact modern location or equation with Ubar is presented as proven.','Un paysage, non une ville nommée comme telle. Aucune localisation moderne exacte ni assimilation à Ubar n’est présentée comme prouvée.'),['hud'],[Q(46,21,26),Q(7,65)],['Ahqaf','Ad','duinen']);

const data={meta:{tradition:'islam',familyScope:L('Geselecteerde familieverbanden uit de Koran en herkenbaar gelabelde islamitische overleveringen. Geen volledige stamboom en geen harmonisatie met de Bijbel. Ouderschap, huwelijk, broer/zus, zorg en voormalige adoptie zijn verschillende relaties. Naamloze personen en onzekerheden blijven zichtbaar.','Selected family connections from the Qur’an and explicitly labelled Islamic traditions. Not a complete genealogy or harmonisation with the Bible. Parenthood, marriage, siblings, care and former adoption are distinct relationships. Unnamed figures and uncertainties remain visible.','Liens familiaux sélectionnés dans le Coran et des traditions islamiques explicitement signalées. Ni généalogie complète ni harmonisation avec la Bible. Parenté, mariage, fratrie, prise en charge et ancienne adoption sont des liens distincts. Anonymat et incertitudes restent visibles.'),placesScope:L('Een selectie van steden, landschappen en heilige plaatsen in Koranverhalen en islamitische herinnering. Bronnen onderscheiden tekst, overlevering en historisch onderzoek. Een gedeelde passage bewijst geen verblijf; religieuze identificatie en archeologisch bewijs worden niet gelijkgesteld.','A selection of cities, landscapes and sacred places in Qur’anic narratives and Islamic remembrance. Sources distinguish scripture, tradition and historical research. A shared passage does not prove residence; religious identification and archaeological evidence are not equated.','Sélection de villes, paysages et lieux sacrés dans les récits coraniques et la mémoire islamique. Les sources distinguent texte sacré, tradition et recherche historique. Un passage commun ne prouve pas une résidence ; identification religieuse et preuve archéologique ne sont pas assimilées.')},families,people,relationships,places};
const quran=JSON.parse(fs.readFileSync(path.join(root,'dist/quran-data.json'),'utf8')),index=JSON.parse(fs.readFileSync(path.join(root,'dist/quran-people.json'),'utf8'));
const ids=new Set(people.map(p=>p.id));assert.equal(ids.size,people.length);
for(const p of people)if(p.indexId)assert(index.people.some(x=>x.id===p.indexId),p.indexId);
for(const x of [...families,...places])for(const k of x.personIds)assert(ids.has(k),k);
for(const e of relationships){assert(ids.has(e.source)&&ids.has(e.target));assert.notEqual(e.source,e.target);}
let passages=0;function validate(x){if(!x||typeof x!=='object')return;if(x.nl!==undefined)for(const lang of ['nl','en','fr'])assert.equal(typeof x[lang],'string');if(x.url)assert.equal(new URL(x.url).protocol,'https:');if(x.passage){const p=x.passage;assert.equal(p.tradition,'islam');assert.equal(p.edition,'nl');const s=quran.surahs.find(s=>s.number===p.surah);assert(s);for(let v=p.verse;v<=p.endVerse;v++)assert(s.ayahs.some(a=>a.number===v),JSON.stringify(p));passages++;}for(const v of Object.values(x))if(typeof v==='object')validate(v);}validate(data);
const target=path.join(root,'dist/tradition-atlas-islam.json'),output=JSON.stringify(data,null,2)+'\n';
if(process.argv.includes('--check'))assert.equal(fs.readFileSync(target,'utf8').replace(/\r\n/g,'\n'),output);else fs.writeFileSync(target,output);
console.log(`Islamic atlas ${process.argv.includes('--check')?'verified':'written'}: ${people.length} people, ${relationships.length} relationships, ${families.length} families, ${places.length} places, ${passages} validated passage occurrences.`);
